-- Curated catalog expansion. Ratings are unassigned (0), not invented IMDb scores.
begin;
update public.movies set "watchSourceUrl"='https://video.blender.org/videos/embed/bf1f3fb5-b119-4f9f-9930-8e20e892b898',"licenseUrl"='https://peach.blender.org/about/',moods=array['happy','cozy','calm'],"durationMinutes"=10 where title='Big Buck Bunny' and "isFree";
update public.movies set "watchSourceUrl"='https://video.blender.org/videos/embed/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40',"licenseUrl"='https://durian.blender.org/about/',moods=array['emotional','epic'],"durationMinutes"=15 where title='Sintel' and "isFree";
update public.movies set "watchSourceUrl"='https://video.blender.org/videos/embed/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5',"licenseUrl"='https://orange.blender.org/download/',moods=array['thoughtful'],"durationMinutes"=11 where title='Elephants Dream' and "isFree";
update public.movies set "watchSourceUrl"='https://video.blender.org/videos/embed/8533ea43-4271-4a57-9694-e9d0b35e1aa1',"licenseUrl"='https://mango.blender.org/about/',moods=array['adrenaline','epic'],"durationMinutes"=13 where title='Tears of Steel' and "isFree";
-- Additional cast; unspecified biography fields retain their schema defaults.
select m."movieID",a."actorID" from (values
('Catch Me If You Can','Tom Hanks'),('The Terminal','Tom Hanks'),('The Truman Show','Jim Carrey'),
('Arrival','Amy Adams'),('Blade Runner 2049','Ryan Gosling'),('Blade Runner 2049','Harrison Ford'),
('The Prestige','Hugh Jackman'),('Prisoners','Hugh Jackman'),('La La Land','Ryan Gosling'),('La La Land','Emma Stone'),
('Groundhog Day','Bill Murray'),('Paddington','Ben Whishaw'),('About Time','Domhnall Gleeson'),('About Time','Rachel McAdams'),
('The Holiday','Kate Winslet'),('The Holiday','Jude Law'),('Dune: Part Two','Timothee Chalamet'),('Dune','Timothee Chalamet')
) as cast_rows(title,name) join public.movies m on m.title=cast_rows.title join public.actors a on a."fullName"=cast_rows.name
on conflict("movieID","actorID") do nothing;
update public.movies set moods=array_append(moods,'romantic') where title='Titanic' and not ('romantic'=any(moods));
commit;
